namespace RecipeHub.Services;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;
    public int RatingCount => Ratings.Count;
}

public class RecipeService
{
    private readonly List<Recipe> _recipes = [];
    private int _nextId = 1;

    public RecipeService()
    {
        SeedData();
    }

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList();

    public IReadOnlyList<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(string title, string category, List<string> ingredients, List<string> steps)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }

    private void SeedData()
    {
        AddRecipe("Classic Pancakes", "Breakfast",
            ["2 cups flour", "2 eggs", "1½ cups milk", "2 tbsp sugar", "1 tsp baking powder", "Pinch of salt"],
            ["Mix dry ingredients together.", "Whisk eggs and milk, then combine with dry mix.", "Heat a buttered pan over medium heat.", "Pour ¼ cup batter per pancake.", "Flip when bubbles form, cook until golden."]);

        AddRecipe("Avocado Toast", "Breakfast",
            ["2 slices sourdough bread", "1 ripe avocado", "Lemon juice", "Red pepper flakes", "Salt and pepper"],
            ["Toast the bread until golden and crisp.", "Mash avocado with lemon juice, salt, and pepper.", "Spread onto toast.", "Sprinkle with red pepper flakes.", "Serve immediately."]);

        AddRecipe("Caesar Salad", "Lunch",
            ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "Caesar dressing", "1 lemon"],
            ["Wash and chop the romaine lettuce.", "Toss lettuce with Caesar dressing.", "Add croutons and shaved parmesan.", "Squeeze fresh lemon over the top.", "Serve chilled."]);

        AddRecipe("Grilled Chicken Wrap", "Lunch",
            ["2 chicken breasts", "4 flour tortillas", "1 cup lettuce", "½ cup tomatoes", "Ranch dressing"],
            ["Season and grill chicken until cooked through.", "Slice chicken into strips.", "Warm tortillas on the grill.", "Layer lettuce, tomato, chicken, and ranch.", "Roll up tightly and slice in half."]);

        AddRecipe("Spaghetti Bolognese", "Dinner",
            ["400g spaghetti", "500g ground beef", "1 onion", "2 cloves garlic", "400g canned tomatoes", "2 tbsp tomato paste", "Italian herbs"],
            ["Cook spaghetti according to package directions.", "Sauté diced onion and garlic in olive oil.", "Add ground beef and brown thoroughly.", "Stir in canned tomatoes, paste, and herbs.", "Simmer for 20 minutes.", "Serve sauce over drained spaghetti."]);

        AddRecipe("Lemon Herb Salmon", "Dinner",
            ["4 salmon fillets", "2 lemons", "Fresh dill", "3 cloves garlic", "Olive oil", "Salt and pepper"],
            ["Preheat oven to 400°F (200°C).", "Place salmon on a lined baking sheet.", "Drizzle with olive oil and lemon juice.", "Top with minced garlic and fresh dill.", "Bake for 12–15 minutes until flaky."]);

        AddRecipe("Chocolate Lava Cake", "Desserts",
            ["200g dark chocolate", "100g butter", "3 eggs", "100g sugar", "2 tbsp flour"],
            ["Preheat oven to 425°F (220°C).", "Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs, then add flour.", "Pour into greased ramekins.", "Bake 12–14 minutes — center should be soft.", "Invert onto plates and serve immediately."]);

        AddRecipe("Strawberry Cheesecake", "Desserts",
            ["250g cream cheese", "100g sugar", "200ml heavy cream", "1 tsp vanilla extract", "200g graham crackers", "80g melted butter", "Fresh strawberries"],
            ["Crush graham crackers and mix with melted butter.", "Press into the bottom of a springform pan.", "Beat cream cheese with sugar and vanilla.", "Whip heavy cream and fold into cheese mixture.", "Pour over crust and refrigerate for 4 hours.", "Top with fresh strawberries before serving."]);

        AddRecipe("Bruschetta", "Appetizers",
            ["1 baguette", "4 ripe tomatoes", "Fresh basil", "2 cloves garlic", "Olive oil", "Balsamic vinegar"],
            ["Slice baguette and toast until golden.", "Dice tomatoes and mix with chopped basil.", "Add minced garlic, olive oil, and balsamic.", "Season with salt and pepper.", "Spoon mixture onto toasted bread."]);

        AddRecipe("Stuffed Mushrooms", "Appetizers",
            ["12 large mushrooms", "100g cream cheese", "50g breadcrumbs", "2 cloves garlic", "Fresh parsley", "Parmesan cheese"],
            ["Preheat oven to 375°F (190°C).", "Remove mushroom stems and chop finely.", "Mix stems with cream cheese, breadcrumbs, garlic, and parsley.", "Fill mushroom caps with the mixture.", "Top with grated parmesan.", "Bake for 20 minutes until golden."]);
    }
}

