@page "/submit"
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation
@rendermode InteractiveServer

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted mb-4">Share your favorite recipe with the community.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>✅ Recipe submitted!</h4>
        <p>Your recipe "<strong>@title</strong>" has been added. <a href="recipe/@newRecipeId">View it here</a>.</p>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <div class="row">
            <div class="col-md-8">
                <div class="mb-3">
                    <label for="title" class="form-label">Recipe Title</label>
                    <InputText id="title" @bind-Value="title" class="form-control" placeholder="e.g., Grandma's Apple Pie" required />
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label">Category</label>
                    <InputSelect id="category" @bind-Value="category" class="form-select" required>
                        <option value="">Select a category...</option>
                        <option value="Breakfast">Breakfast</option>
                        <option value="Lunch">Lunch</option>
                        <option value="Dinner">Dinner</option>
                        <option value="Desserts">Desserts</option>
                        <option value="Appetizers">Appetizers</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                    <InputTextArea id="ingredients" @bind-Value="ingredientsText" class="form-control" rows="6"
                        placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" required />
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label">Steps (one per line)</label>
                    <InputTextArea id="steps" @bind-Value="stepsText" class="form-control" rows="6"
                        placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." required />
                </div>

                <button type="submit" class="btn btn-primary btn-lg"
                    disabled="@(!IsValid)">
                    Submit Recipe
                </button>
            </div>

            <div class="col-md-4">
                <div class="card bg-light">
                    <div class="card-body">
                        <h5>💡 Tips</h5>
                        <ul class="small mb-0">
                            <li>Be specific with measurements</li>
                            <li>List ingredients in order of use</li>
                            <li>Write clear, numbered steps</li>
                            <li>Include cooking times and temperatures</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    </EditForm>
}

@code {
    private string title = "";
    private string category = "";
    private string ingredientsText = "";
    private string stepsText = "";
    private bool submitted;
    private int newRecipeId;

    private bool IsValid =>
        !string.IsNullOrWhiteSpace(title) &&
        !string.IsNullOrWhiteSpace(category) &&
        !string.IsNullOrWhiteSpace(ingredientsText) &&
        !string.IsNullOrWhiteSpace(stepsText);

    private void HandleSubmit()
    {
        if (!IsValid) return;

        var ingredients = ingredientsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        var steps = stepsText
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        RecipeService.AddRecipe(title, category, ingredients, steps);

        var added = RecipeService.GetByCategory(category).LastOrDefault();
        newRecipeId = added?.Id ?? 0;
        submitted = true;
    }
}

@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="d-inline-block">
    <div class="d-flex align-items-center gap-2">
        <span class="star-rating" role="group" aria-label="Rate this recipe">
            @for (int i = 1; i <= 5; i++)
            {
                var star = i;
                <button type="button"
                    class="btn btn-link p-0 fs-4 text-decoration-none @(star <= (hoverStar ?? 0) ? "text-warning" : (star <= Math.Round(CurrentRating) ? "text-warning" : "text-muted"))"
                    @onclick="() => Rate(star)"
                    @onmouseover="() => hoverStar = star"
                    @onmouseout="() => hoverStar = null"
                    aria-label="@star stars">
                    @(star <= (hoverStar ?? (int)Math.Round(CurrentRating)) ? "★" : "☆")
                </button>
            }
        </span>

        <span class="text-muted small">
            @if (justRated)
            {
                <span class="text-success fw-bold">Thanks for rating!</span>
            }
            @CurrentRating.ToString("F1") (@RatingCount ratings)
        </span>
    </div>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int? hoverStar;
    private bool justRated;

    private void Rate(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        justRated = true;
    }
}

